// CSD_RATIONALE_BEGIN
// Diagnosis from the attempt ledger and failure rollouts:
//
// Best result (52%, attempt 43) uses the structure:
//   5-step unconstrained preamble → OpenConstrainedSpan → GroupBoostedConstrainedStep(6.0)
//   with IsCompletePrefix-gated early close → CloseSpanWithinBudget(80) fallback.
//
// The current 33.7% (attempt 56) regressed by replacing GroupBoostedConstrainedStep
// with RegenerateUnitOnGroundingFailure, which produced 181/300 semantic mismatches
// (worse than the 141 from the 52% approach).
//
// The failure clusters show 174/199 wrong answers are syntax-valid but semantically
// incorrect. Primary observed failure patterns:
//   (A) Table aliases (h, f, t) used instead of full table names → wrong join keys
//   (B) COUNT(column) used instead of COUNT(*) → wrong counts when NULLs present
//   (C) LEFT JOIN used instead of JOIN → wrong cardinality in results
//   (D) Extra columns, AS aliases not matching expected canonical form
//   (E) Repetition loops (SELECT col, col, col...) before FROM clause reached
//
// This attempt returns to the proven 52% base structure and targets the remaining
// 48% gap exclusively through improved task guidance that explicitly prohibits the
// observed failure patterns.
//
// Changes from attempt 43:
//   1. New focused guidance: explicitly forbids table aliases, mandates COUNT(*),
//      mandates JOIN over LEFT JOIN, demands full table names, discourages
//      redundant columns. These rules target patterns A-D above.
//   2. No structural changes (same phase layout, same helpers, same budget splits).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (unconstrained preamble, while !insideConstrainedOut):
//   The loop guard includes !insideConstrainedOut. insideConstrainedOut flips true only
//   when RenderedEndsWith fires, at which point we set currentConstrainedOut := [].
//   parser.IsValidPrefix([]) holds by the method precondition. On EOS break,
//   insideConstrainedOut stays false, making the implication vacuously true.
//
// Phase 2 (OpenConstrainedSpan):
//   Guarded by !insideConstrainedOut. The helper sets currentConstrainedOut := [];
//   IsValidPrefix([]) holds by precondition. steps grows by 1.
//
// Phase 3 (main constrained loop):
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//   making the implication vacuously true; currentConstrainedOut := []. steps += 1.
//   Normal step branch: GroupBoostedConstrainedStep hard-masks to parser-valid tokens
//   plus EOS. AppendConstrainedToken extends currentConstrainedOut by one parser-valid
//   token, so IsValidPrefix is preserved by the parser extension property. steps += 1.
//   EOS branch: CloseConstrainedSpan called only when IsCompletePrefix already holds;
//   sets insideConstrainedOut := false. steps += at most 2.
//
// Phase 4 (CloseSpanWithinBudget):
//   The helper's postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 on EOS, 1 on non-EOS). The 1:1 ratio preserves the bound.
// Phase 2: OpenConstrainedSpan appends exactly 1 "<<" token and steps grows by 1.
//   Net growth 1:1, bound preserved.
// Phase 3: IsCompletePrefix branch: steps += 1, CloseConstrainedSpan appends at most
//   1 ">>" token (≤1:1). Normal branch: GroupBoostedConstrainedStep costs 1 step,
//   AppendConstrainedToken appends 1 visible token (1:1). EOS+close path: at most
//   2 steps consumed, at most 1 visible token appended (">>" at close); bound holds.
// Phase 4: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + closeBudget
//   and steps := steps_before + closeBudget. By induction |generated| <= |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a correct SQL query answering the question. Place ONLY the SQL between << and >>. STRICT RULES: (1) Use the EXACT table and column names from the schema - never invent names. (2) Do NOT use table aliases like 'h', 't', or 'f' - write the full table name everywhere (e.g. highschooler.name not h.name). (3) Use COUNT(*) for counting rows, not COUNT(column). (4) Use JOIN (inner join) by default, not LEFT JOIN or LEFT OUTER JOIN, unless the question specifically requires outer join semantics. (5) Write only the columns the question asks for. (6) Do not repeat the same column name in the SELECT list.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (≤5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with schema-token boosting
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

